function send(metric) {
  const a = metric.attribution;
  const body = {
    name: metric.name,            // "LCP" | "INP" | "CLS"
    value: metric.value,          // ms for LCP and INP, a unitless number for CLS
    id: metric.id,                // id of this page load, to dedupe server-side
    // what exactly was slow:
    target: a.target ?? a.interactionTarget ?? a.largestShiftTarget,
    inputDelay: a.inputDelay,
    processingDuration: a.processingDuration,
    presentationDelay: a.presentationDelay,
    elementRenderDelay: a.elementRenderDelay,
  };
  navigator.sendBeacon("/rum", JSON.stringify(body)); // delivered even if the tab is closing
}

onLCP(send);
onINP(send);
onCLS(send);

input.addEventListener("input", (e) => {
  updateComposer(e);                  // only what the next frame needs
  requestAnimationFrame(() => {       // after the frame is painted...
    setTimeout(() => {                // ...in a separate task
      updateWordCount();
      checkSpelling();
      saveDraft();
    }, 0);
  });
