// yield to the main thread: scheduler.yield where it exists, setTimeout otherwise
function yieldToMain() {
  if (globalThis.scheduler?.yield) return scheduler.yield();
  return new Promise((resolve) => setTimeout(resolve, 0));
}

async function processInChunks(rows) {
  let lastYield = performance.now();
  for (const row of rows) {
    formatRow(row);                                  // real work for one row
    if (performance.now() - lastYield > 50) {        // been on the main thread ~50 ms?
      await yieldToMain();                           // let the browser paint a frame and handle input
      lastYield = performance.now();
    }
  }
}

